import heapq

def match(orders):
    trades = []
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    seq_counter = 0
    book = {}  # id -> dict with price, qty, side, seq, active

    def add_to_book(oid):
        o = book[oid]
        if o['side'] == 'buy':
            heapq.heappush(buy_heap, (-o['price'], o['seq'], oid))
        else:
            heapq.heappush(sell_heap, (o['price'], o['seq'], oid))

    def top_valid(heap):
        while heap:
            item = heap[0]
            oid = item[2]
            o = book.get(oid)
            if o is None or o['qty'] <= 0 or not o.get('active', True):
                heapq.heappop(heap)
                continue
            return item
        return None

    def match_incoming(incoming_id, side, price, qty, is_market):
        remaining = qty
        opp_heap = sell_heap if side == 'buy' else buy_heap
        while remaining > 0:
            top = top_valid(opp_heap)
            if top is None:
                break
            resting_id = top[2]
            resting = book[resting_id]
            resting_price = resting['price']
            if not is_market:
                if side == 'buy' and resting_price > price:
                    break
                if side == 'sell' and resting_price < price:
                    break
            trade_qty = min(remaining, resting['qty'])
            if side == 'buy':
                trades.append([incoming_id, resting_id, resting_price, trade_qty])
            else:
                trades.append([resting_id, incoming_id, resting_price, trade_qty])
            resting['qty'] -= trade_qty
            remaining -= trade_qty
            if resting['qty'] <= 0:
                resting['active'] = False
                heapq.heappop(opp_heap)
        return remaining

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                book[oid]['active'] = False
                book[oid]['qty'] = 0
            continue

        incoming_id = order[1]
        side = order[2]

        if typ == 'market':
            qty = order[3]
            match_incoming(incoming_id, side, None, qty, True)
            # remainder discarded, not added to book
        else:
            price = order[3]
            qty = order[4]
            remaining = match_incoming(incoming_id, side, price, qty, False)
            if typ == 'limit':
                if remaining > 0:
                    seq_counter += 1
                    book[incoming_id] = {
                        'price': price,
                        'qty': remaining,
                        'side': side,
                        'seq': seq_counter,
                        'active': True
                    }
                    add_to_book(incoming_id)
            # ioc: remainder discarded

    return trades

